package rw.schoolpass.web;
import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import rw.schoolpass.model.SchoolProfile; import rw.schoolpass.repo.SchoolProfileRepository; import rw.schoolpass.service.AuditService;
@Controller @RequestMapping("/admin/settings") public class SettingsController {private final SchoolProfileRepository repo;private final AuditService audit;public SettingsController(SchoolProfileRepository r,AuditService a){repo=r;audit=a;} @GetMapping String page(Model m){m.addAttribute("profile",repo.findById(1L).orElseGet(SchoolProfile::new));return "settings";} @PostMapping String save(@ModelAttribute SchoolProfile p,Authentication auth){p.setSchoolName(p.getSchoolName().trim());p.setPrincipalName(p.getPrincipalName().trim());p.setAcademicYear(p.getAcademicYear().trim());p.setContactPhone(p.getContactPhone().trim());p.setContactEmail(p.getContactEmail().trim());p.setAddress(p.getAddress().trim());p.setId(1L);repo.save(p);audit.log(auth.getName(),"SCHOOL_PROFILE_UPDATED","SCHOOL","1","School profile updated");return "redirect:/admin/settings?saved=true";} }
